"""Lampiran I sampai O: segmentasi, rancangan produk, pengolahan data, dampak, bisnis, implementasi, kelayakan.
Angka diambil dari analysis2.json agar naskah dan gambar selalu sama. Blok memakai format content.py."""
import analysis2

A = analysis2.load()


def d(x, n=0):
    return f"{x:.{n}f}".replace(".", ",")


def pct(x, n=0):
    return f"{x * 100:.{n}f}%".replace(".", ",")


def rp(x):
    return f"{x:,.0f}".replace(",", ".")


def juta(x, n=1):
    return f"Rp{d(x / 1e6, n)} juta"


def jt(x):
    """Juta rupiah untuk sel tabel, tanda minus benar."""
    return f"{x / 1e6:,.1f}".replace(",", "#").replace(".", ",").replace("#", ".").replace("-", "−")


