      ["Sensitivitas kejadian (G1)", "1.000 batuk", f"{pct(SE['1000'][0], 1)} sampai {pct(SE['1000'][1], 1)}", "Dipakai pada G1 penuh sebelum pilot"],
      ["Alarm palsu (G1)", "5 jam", f"{d(FA['5'][0], 2)} sampai {d(FA['5'][1], 2)} per jam", "Tidak cukup; hanya untuk uji asap"],
